#!/usr/bin/env python3
"""Regenerate smaa_glsl.inc from the vendored SMAA.hlsl.

The OpenGL renderer compiles SMAA from source at runtime (SMAA_GLSL_3), so the
shader has to live in the binary as a C string. Comments are stripped because
SMAA.hlsl is Latin-1 and some GL drivers reject non-ASCII bytes even inside
GLSL comments; the license travels in the generated file's header instead.

    python gen_smaa_glsl.py
"""
import pathlib
import re

HERE = pathlib.Path(__file__).resolve().parent
SRC = HERE / "SMAA.hlsl"
OUT = HERE / "smaa_glsl.inc"


def strip_comments(text: str) -> str:
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
    return re.sub(r"//[^\n]*", "", text)


def main() -> None:
    raw = SRC.read_bytes().decode("latin-1").replace("\r\n", "\n")
    code = strip_comments(raw)
    lines = [ln.rstrip() for ln in code.split("\n")]
    out_lines = []
    for ln in lines:
        if not ln and (not out_lines or not out_lines[-1]):
            continue
        out_lines.append(ln)
    for ln in out_lines:
        if any(ord(c) > 127 for c in ln):
            raise SystemExit(f"non-ASCII code line survived: {ln!r}")
        if "\\" in ln:
            raise SystemExit(f"line continuation not supported: {ln!r}")

    license_text = (HERE / "LICENSE.txt").read_text(encoding="ascii")
    body = ["/* GENERATED by gen_smaa_glsl.py from SMAA.hlsl -- do not edit.", " *"]
    body += [(" * " + ln).rstrip() for ln in license_text.strip().split("\n")]
    body += [" */", "static const char SMAA_GLSL_SRC[] ="]
    body += ['    "' + ln.replace('"', '\\"') + '\\n"' for ln in out_lines]
    body[-1] += ";"
    OUT.write_text("\n".join(body) + "\n", encoding="ascii", newline="\n")
    print(f"wrote {OUT} ({len(out_lines)} lines)")


if __name__ == "__main__":
    main()
